const icons={bag:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M6 8h12l-1 12H7L6 8Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/></svg>',heart:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.9-8.6a5.5 5.5 0 0 0-.1-7.8Z"/></svg>',search:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><circle cx="11" cy="11" r="6.5"/><path d="m16 16 4 4"/></svg>',menu:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M3 7h18M3 12h18M3 17h18"/></svg>',user:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><circle cx="12" cy="8" r="3.5"/><path d="M4.5 21a7.5 7.5 0 0 1 15 0"/></svg>'};
const products=[
{slug:'dark-monsoon',name:'Dark Monsoon',notes:'Rain • Earth • Oud',subtitle:'The Power After the Storm',description:'Deep, atmospheric and quietly commanding. Dark Monsoon captures the feeling of rain settling into the earth — where freshness meets depth and oud leaves behind a powerful, lingering presence.',mood:'Powerful',character:'Deep • Earthy • Mysterious',image:'/products/dark Monsoon.png',accent:'#afb7a8',price:1499},
{slug:'royal-zafran-rose',name:'Royal Zafran Rose',notes:'Saffron • Rose • Agarwood',subtitle:'A Rose, Made Royal.',description:'An opulent interpretation of timeless rose, enriched with the warmth of zafran and the depth of agarwood. Rich, elegant and unmistakably regal.',mood:'Regal',character:'Rich • Floral • Opulent',image:'/products/royal zefran rose.png',accent:'#c8aca2',price:1499},
{slug:'golden-ritual',name:'Golden Ritual',notes:'Coffee • Vanilla • Amber',subtitle:'Warmth Becomes a Ritual.',description:'The comforting richness of coffee meets smooth vanilla and glowing amber. Warm, enveloping and intimate — a fragrance inspired by the rituals we return to again and again.',mood:'Comforting',character:'Warm • Sweet • Intimate',image:'/products/golden ritual.png',accent:'#c8aa72',price:1499},
{slug:'golden-leaf',name:'Golden Leaf',notes:'Tobacco • Honey • Tonka',subtitle:'Wrapped in Golden Warmth.',description:'A rich tobacco accord softened by honey and the smooth warmth of tonka. Confident and refined, Golden Leaf leaves a warm impression that stays close to the skin.',mood:'Bold',character:'Warm • Refined • Confident',image:'/products/golden leaf.png',accent:'#b89a5e',price:1499},
{slug:'crystal-bloom',name:'Crystal Bloom',notes:'Water • Aromatic Air • Florals',subtitle:'Where Water Becomes a Flower.',description:'Clean, luminous and effortlessly fresh. Crystal Bloom evokes clear water, open air and delicate flowers awakening in the first light of morning.',mood:'Fresh',character:'Clean • Luminous • Airy',image:'/products/crystal bloom.png',accent:'#b4cdd1',price:1499},
{slug:'flora-silk',name:'Flora Silk',notes:'Soft Florals • Elegant Bouquet',subtitle:'Flowers, Draped in Silk.',description:'A graceful bouquet inspired by the softness of petals against silk. Delicate yet memorable, Flora Silk expresses understated elegance through a beautifully composed floral character.',mood:'Elegant',character:'Soft • Floral • Graceful',image:'/products/flora silk.png',accent:'#cfbdc6',price:1499}];
const reviews={'dark-monsoon':[{name:'Arjun M.',rating:5,date:'Aug 2026',text:'Opens with a rush of something dark and wet — like stepping into a forest after heavy rain. By the drydown it\'s all oud and warm earth. Wore it to a dinner party and my friend asked me three times what I was wearing.',verified:true},{name:'Priya K.',rating:5,date:'Jul 2026',text:'Not for the faint-hearted. This one announces you before you enter a room. I save it for evenings when I want to feel commanding.',verified:true},{name:'Vikram S.',rating:4,date:'Jul 2026',text:'The longevity is insane. Sprayed it on my kurta before a wedding and could still smell traces of it two days later.',verified:true},{name:'Meera R.',rating:5,date:'Jun 2026',text:'My husband rarely notices fragrances but this one stopped him mid-conversation. He actually borrowed it the next day.',verified:true},{name:'Rahul D.',rating:4,date:'Jun 2026',text:'Beautiful blend but needs a couple of hours to settle. The opening is a bit sharp, but once it calms down, it\'s magnificent.',verified:false}],'royal-zafran-rose':[{name:'Ananya S.',rating:5,date:'Aug 2026',text:'This is what I imagine a Mughal garden smells like at sunset. The saffron gives it a warmth that elevates the rose beyond anything I\'ve tried.',verified:true},{name:'Kavya P.',rating:5,date:'Jul 2026',text:'Bought this for my mother\'s birthday. She called me in tears — said it reminded her of her grandmother\'s home. That\'s the kind of fragrance this is.',verified:true},{name:'Deepak J.',rating:4,date:'Jul 2026',text:'Elegant without being old-fashioned. I wore it to an art gallery opening and felt perfectly dressed.',verified:true},{name:'Ritu M.',rating:5,date:'Jun 2026',text:'The rose here isn\'t sweet or powdery — it\'s regal and complex. You can feel the saffron weaving through it like a gold thread.',verified:true},{name:'Nikhil B.',rating:4,date:'May 2026',text:'A bit too floral for casual wear. But for weddings, celebrations, evenings out — absolutely perfect.',verified:false}],'golden-ritual':[{name:'Shreya T.',rating:5,date:'Aug 2026',text:'This is my comfort fragrance. Coffee and vanilla without smelling like a dessert — it\'s warm and sophisticated. My morning ritual now starts with two sprays.',verified:true},{name:'Aman G.',rating:5,date:'Jul 2026',text:'Reminds me of Sunday mornings with filter coffee and old songs. Not trying to be loud, just quietly beautiful.',verified:true},{name:'Rohan K.',rating:5,date:'Jul 2026',text:'My girlfriend stole my bottle after trying it once. Had to order another one for myself. Take that as the highest compliment.',verified:true},{name:'Pooja N.',rating:4,date:'Jun 2026',text:'Perfect winter fragrance. The amber base keeps it grounded while the vanilla gives it just enough sweetness.',verified:true},{name:'Aditya V.',rating:4,date:'May 2026',text:'Wore it on a first date. Three dates later, she said she fell in love with the scent before she fell in love with me.',verified:false}],'golden-leaf':[{name:'Sanjay R.',rating:5,date:'Aug 2026',text:'The tobacco note here is nothing like cigarette smoke — it\'s smooth, almost leathery. Combined with the honey, it creates something truly distinctive.',verified:true},{name:'Ishaan M.',rating:5,date:'Jul 2026',text:'I keep reaching for this one when I need confidence. Job interviews, presentations, important meetings — Golden Leaf is my silent partner.',verified:true},{name:'Tara L.',rating:4,date:'Jun 2026',text:'Sophisticated without being stuffy. My colleagues keep asking what I\'m wearing and I keep dodging the question.',verified:true},{name:'Karthik S.',rating:5,date:'Jun 2026',text:'The drydown is extraordinary — warm tonka and a hint of something resinous that stays close to skin.',verified:true},{name:'Nandini D.',rating:4,date:'May 2026',text:'Slightly masculine-leaning but I wear it confidently as a woman. The honey softens everything beautifully.',verified:false}],'crystal-bloom':[{name:'Anita W.',rating:5,date:'Aug 2026',text:'Opens slightly fresh on my skin and settles into a very soft floral scent. I wore it to dinner and could still smell it on my clothes the next morning.',verified:true},{name:'Raj P.',rating:4,date:'Jul 2026',text:'This is the fragrance equivalent of stepping out of a shower into a garden. Clean but alive.',verified:true},{name:'Sonal K.',rating:5,date:'Jul 2026',text:'Perfect for Indian summers when everything else feels too heavy. Crystal Bloom breathes.',verified:true},{name:'Aarav M.',rating:4,date:'Jun 2026',text:'My go-to for office wear. Professional without being boring, fresh without being generic.',verified:true},{name:'Divya S.',rating:5,date:'May 2026',text:'Subtler than the other Sixth Ritu fragrances but that\'s its strength. People lean in closer — which is exactly the point.',verified:false}],'flora-silk':[{name:'Meghna J.',rating:5,date:'Aug 2026',text:'Like wearing a silk dupatta made of flowers. This fragrance drapes rather than projects, and that elegance is what makes it special.',verified:true},{name:'Farah A.',rating:5,date:'Jul 2026',text:'Bought this sight unseen based on the description and wasn\'t disappointed. Delicate but present — you notice it the way you notice someone graceful entering a room.',verified:true},{name:'Priyanka S.',rating:4,date:'Jun 2026',text:'I\'ve been searching for a fragrance that feels feminine without being sweet. Flora Silk is exactly that.',verified:true},{name:'Ankit R.',rating:4,date:'Jun 2026',text:'Applied it before a long flight. Eight hours later, a flight attendant complimented me on it. The lasting power surprised me given how light it feels.',verified:true},{name:'Sunita V.',rating:5,date:'May 2026',text:'My mother says it smells like the jasmines she grew up with, but more refined. I think that\'s the perfect description.',verified:false}]};
const route=location.pathname.replace(/\/index\.html$/,'').replace(/\/$/,'')||'/';const app=document.querySelector('#app');let cart=JSON.parse(localStorage.getItem('tsr-cart')||'[]');let wishes=JSON.parse(localStorage.getItem('tsr-wishes')||'[]');let coupon=localStorage.getItem('tsr-coupon')||'';let activeMood=0;let slide=0;let heroPaused=false;var cmsPages={};var cmsPopup=null;
const link=(path,label,cls='')=>`<a class="${cls}" href="${path}" data-link>${label}</a>`;const bySlug=s=>products.find(p=>p.slug===s);const money=()=>'';const persist=()=>{localStorage.setItem('tsr-cart',JSON.stringify(cart));localStorage.setItem('tsr-wishes',JSON.stringify(wishes));localStorage.setItem('tsr-coupon',coupon);};
function header(){return `<div class="announcement"><span>Discover The Sixth Ritu — A New Season of Fine Fragrance</span></div><header class="header"><button class="icon-btn mobile-menu" data-menu aria-label="Open menu">${icons.menu}</button><a class="brand" href="/" data-link><img src="/logo.png" alt="The Sixth Ritu" /></a><nav class="nav" aria-label="Primary navigation">${link('/','Home')}${link('/shop','Shop')}${link('/collection','The Collection')}${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/contact','Contact')}</nav><div class="tools"><button class="icon-btn" data-search aria-label="Search">${icons.search}</button>${link('/account',icons.user,'icon-btn')}<button class="icon-btn" data-wishlist aria-label="Wishlist">${icons.heart}</button><button class="icon-btn" data-cart aria-label="Bag">${icons.bag}<span class="count">${cart.reduce((a,i)=>a+i.qty,0)}</span></button></div></header><div class="menu-panel" id="menu"><button class="icon-btn close-menu" data-menu aria-label="Close menu">×</button><a class="brand" href="/" data-link><img src="/logo.png" alt="The Sixth Ritu" /></a><nav>${link('/','Home')}${link('/shop','Shop')}${link('/collection','The Collection')}${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/contact','Contact')}${link('/wishlist','Wishlist')}${link('/cart','Bag')}</nav></div>`}
function footer(){return `<section class="newsletter section"><div class="container newsletter-grid"><div><p class="eyebrow">Enter the world of The Sixth Ritu</p><h2 class="display">Stay in the Season.</h2></div><div><p>Be the first to discover new creations, private releases and stories from The Sixth Ritu.</p><form class="email-form" data-newsletter><input aria-label="Your email address" type="email" placeholder="Your Email Address" required/><button>Join →</button></form><p class="form-note">By subscribing, you agree to receive communications from The Sixth Ritu.</p></div></div></section><footer class="footer"><div class="container"><div class="footer-top"><div class="footer-brand"><img src="/logo.png" alt="The Sixth Ritu"/><p>Fragrances inspired by emotion, created to become memory.</p></div><div><h3>Shop</h3>${products.map(p=>link('/product/'+p.slug,p.name)).join('')}</div><div><h3>Discover</h3>${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/collection','Our Philosophy')}${link('/contact','Contact Us')}</div><div><h3>Customer Care</h3>${link('/shipping','Shipping & Delivery')}${link('/returns','Returns & Exchanges')}${link('/faq','FAQs')}${link('/track-order','Track Order')}</div></div><div class="footer-bottom"><span>© 2026 The Sixth Ritu. All Rights Reserved.</span><span>${link('/privacy','Privacy')} &nbsp; ${link('/terms','Terms')}</span></div></div></footer>`}
function productCard(p){const hd=p.mrp&&p.mrp>p.price;return `<div class="v3-prod-card"><div class="v3-prod-card-img">${hd?'<span class="v3-prod-card-badge">Sale</span>':''}<button class="card-wish ${wishes.includes(p.slug)?'active':''}" data-wish="${p.slug}" aria-label="Save ${p.name}">${icons.heart}</button><a href="/product/${p.slug}" data-link><img src="${p.image}" alt="${p.name}" loading="lazy"/></a></div><h3><a href="/product/${p.slug}" data-link>${p.name}</a></h3><p class="v3-prod-card-char">${p.character}</p><p class="v3-prod-card-spec">Extrait de Parfum · 50 ML</p><p class="v3-prod-card-price">${hd?`<del>₹${p.mrp.toLocaleString('en-IN')}</del> `:''}₹${p.price.toLocaleString('en-IN')}</p><div class="v3-prod-card-actions"><button data-add="${p.slug}">Add to Bag</button><button data-quick="${p.slug}">Quick View</button></div></div>`}
function home(){let p=products[0];return `<main id="main"><section class="hero" aria-label="The Sixth Ritu introduction">${[0,1,2].map((i)=>{let hp=products[[0,1,4][i]];let copy=[['THE SIXTH RITU','A Season Beyond the Six.','India has always known six seasons. We created one more — a season experienced through scent.','Discover The Collection','/collection','Our Story','/about'],['THE COLLECTION','Six Fragrances. Six Stories.','From rain-soaked earth and royal rose to golden amber and delicate florals, discover moments that remain with you.','Explore All Fragrances','/shop','',''],['FINE FRAGRANCE • INDIAN IMAGINATION • MODERN LUXURY','Made to Be Remembered.','Not simply a fragrance you wear, but a feeling that becomes part of your story.','Find Your Ritu','#find','','']][i];return `<div class="hero-slide ${i===0?'active':''}"><div class="hero-copy"><p class="eyebrow">${copy[0]}</p><h1 class="display">${copy[1]}</h1><p>${copy[2]}</p><div class="hero-actions">${link(copy[4],copy[3],'btn')}${copy[6]?link(copy[6],copy[5],'btn btn-light'):''}</div></div><div class="hero-product"><img src="${hp.image}" alt="${hp.name} fragrance" /></div></div>`}).join('')}<div class="hero-ui"><div class="dots">${[0,1,2].map(i=>`<button class="dot ${i===0?'active':''}" data-slide="${i}" aria-label="Show slide ${i+1}"></button>`).join('')}</div><div class="hero-arrows"><button data-slide-prev aria-label="Previous slide">←</button><button data-slide-next aria-label="Next slide">→</button></div></div></section><section class="section"><div class="container intro"><div><p class="eyebrow">Welcome to The Sixth Ritu</p><h2 class="display">Some Seasons Change the World.<br/>Others Stay With You.</h2></div><div class="intro-body"><p>India has always known six seasons — Vasanta, Grishma, Varsha, Sharad, Hemanta and Shishira. Each transforms the world around us and leaves behind a feeling.</p><p>We imagine another. A season found in the scent of rain after a storm, the warmth of an evening ritual, flowers resting on silk, or the memory of someone after they have gone.</p>${link('/about','Discover Our Story','text-link')}</div></div></section><section class="signature section"><div class="container"><div class="section-head"><div><p class="eyebrow">The Signature Collection</p><h2 class="display">Discover Your Ritu.</h2></div><p>Six distinctive fragrances. Six different moods. Created for the moments you want to remember.</p></div><div class="feature-rail" id="feature"><div class="feature-image"><img src="${p.image}" alt="${p.name} fragrance"/></div><div class="feature-details"><span class="feature-no">01 — 06</span><p class="notes">${p.notes}</p><h3 class="display">${p.name}</h3><h4>${p.subtitle}</h4><p>${p.description}</p>${link('/product/'+p.slug,'Explore '+p.name,'text-link')}<div class="rail-nav">${products.map((x,i)=>`<button class="${i===0?'active':''}" data-feature="${i}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div></div></div></div></section><section class="mood" id="find"><div class="container mood-grid"><div class="mood-copy"><p class="eyebrow">Choose by Mood</p><h2 class="display">What Is Your Ritu Today?</h2><p>I want something...</p><div class="mood-list">${products.map((p,i)=>`<button class="mood-choice ${i===0?'active':''}" data-mood="${i}">${p.mood}</button>`).join('')}</div></div><div class="mood-visual"><img src="${p.image}" alt="${p.name} fragrance"/><div class="mood-caption"><h3>${p.name}</h3><p>${p.character}</p></div></div></div></section><section class="seasons"><div class="seasons-content"><p class="eyebrow">The Inspiration</p><h2 class="display">India Knows<br/>Six Seasons.</h2><div class="season-list"><span>VASANTA<small>New Beginnings</small></span><span>GRISHMA<small>Heat & Radiance</small></span><span>VARSHA<small>Rain & Renewal</small></span><span>SHARAD<small>Clarity</small></span><span>HEMANTA<small>Golden Warmth</small></span><span>SHISHIRA<small>Stillness</small></span></div><p>And Then, There Is One More.</p><div class="seasons-final">THE SIXTH RITU</div><p>A season without a date. A season experienced through scent.</p>${link('/the-sixth-ritu','Discover The Sixth Ritu','text-link')}</div></section><section class="philosophy"><div class="philosophy-copy"><p class="eyebrow">Our Philosophy</p><h2 class="display">Made to Be Worn.<br/>Created to Be Remembered.</h2><p>Every fragrance begins with a feeling. We translate that feeling through scent — bringing together Indian imagination, expressive perfume ingredients and a contemporary approach to luxury.</p>${link('/the-sixth-ritu','Our Philosophy','text-link')}</div><div class="philosophy-art"><img src="${products[2].image}" alt="Golden Ritual fragrance" loading="lazy"/></div></section><section class="campaign"><div class="campaign-content"><p class="eyebrow">The Season of Luxury</p><h2 class="display">A Memory Has No Season.</h2>${link('/collection','Explore The Collection','btn')}</div></section><section class="section"><div class="container"><div class="section-head"><div><p class="eyebrow">Shop by Character</p><h2 class="display">Find a Fragrance That Feels Like You.</h2></div></div><div class="character-grid">${products.map(p=>`<a class="character" href="/product/${p.slug}" data-link><h3>${p.mood} &<br/>${p.character.split(' • ')[1]||'Memorable'}</h3><p>Explore ${p.name} →</p></a>`).join('')}</div></div></section><section class="section"><div class="container art"><div class="art-text"><p class="eyebrow">The Art of Fragrance</p><h2 class="display">More Than a Fragrance. A Personal Ritual.</h2><p>A fragrance becomes meaningful through the moments connected to it. A first impression. A familiar evening. A celebration. A journey. A person.</p></div><div class="art-quote">The Sixth Ritu is created for those moments — fragrances designed to become part of your presence and, eventually, part of your memory.</div></div></section><section class="section"><div class="container"><div class="section-head"><div><p class="eyebrow">The Collection</p><h2 class="display">Six expressions of one idea.</h2></div>${link('/shop','Shop All','text-link')}</div><div class="product-grid">${products.map(productCard).join('')}</div></div></section><section class="statement"><blockquote>“We do not create fragrances merely to be worn. We create them to be remembered.”</blockquote><cite>— The Sixth Ritu</cite></section><section class="section social"><div class="container"><div class="social-head"><div><p class="eyebrow">Follow the Season</p><h2 class="display">@TheSixthRitu</h2></div><a href="#newsletter" class="text-link">Follow Our Journey</a></div><div class="social-rack"><div class="social-piece"><img src="${products[1].image}" alt="Royal Zafran Rose" loading="lazy"/></div><div class="social-piece"><img src="${products[4].image}" alt="Crystal Bloom" loading="lazy"/></div><div class="social-piece"><img src="${products[5].image}" alt="Flora Silk" loading="lazy"/></div></div></div></section></main>`}
function pageHero(kicker,title,copy=''){return `<section class="page-hero"><div class="container"><p class="eyebrow">${kicker}</p><h1 class="display">${title}</h1>${copy?`<p>${copy}</p>`:''}</div></section>`}
function shop(){return `<main id="main">${pageHero('The Signature Collection','Discover Your Ritu.','Six distinctive fragrances. Six different moods. Created for the moments you want to remember.')}<section class="section"><div class="container"><div class="shop-toolbar"><span>${products.length} fragrances</span><label>Sort <select class="select" data-sort><option value="name">Collection order</option><option value="az">Name: A–Z</option></select></label></div><div class="product-grid" id="shop-grid">${products.map(productCard).join('')}</div></div></section></main>`}
function reviewSection(p){const pr=reviews[p.slug]||[];if(!pr.length)return '';const avg=(pr.reduce((a,r)=>a+r.rating,0)/pr.length).toFixed(1);const counts=[5,4,3,2,1].map(s=>pr.filter(r=>r.rating===s).length);return `<section class="product-reviews section"><div class="container"><div class="reviews-header"><div><h2 class="display">Reviews</h2><div class="reviews-summary-block"><span class="reviews-big-score">${avg}</span><div><div class="reviews-stars-lg">${'★'.repeat(Math.round(avg))}${'☆'.repeat(5-Math.round(avg))}</div><span class="reviews-count-text">${pr.length} Review${pr.length===1?'':'s'}</span></div></div></div><div class="reviews-bars">${counts.map((c,i)=>`<div class="review-bar"><span>${5-i}★</span><div class="bar"><div class="bar-fill" style="width:${pr.length?Math.round(c/pr.length*100):0}%"></div></div><span>${c}</span></div>`).join('')}</div></div><button class="review-write-btn" data-write-review>Write a Review</button><div class="reviews-list">${pr.map(r=>`<div class="review-card"><div class="review-card-top"><div class="review-card-stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><div class="review-card-meta"><span class="review-card-author">${r.name}</span><span>${r.date}</span>${r.verified?'<span class="review-verified">✓ Verified Purchase</span>':''}</div></div><p class="review-card-text">${r.text}</p></div>`).join('')}</div><div class="review-form-wrap" id="review-form" style="display:none"><h3>Write a Review</h3><form data-review-form><div class="review-rating-row"><span>Your Rating</span><div class="review-star-input">${[1,2,3,4,5].map(s=>`<button type="button" data-star="${s}" aria-label="${s} star${s>1?'s':''}" class="">☆</button>`).join('')}</div></div><div class="field"><label for="rev-name">Name</label><input id="rev-name" placeholder="Your name" required/></div><div class="field"><label for="rev-title">Review Title</label><input id="rev-title" placeholder="Sum it up" required/></div><div class="field"><label for="rev-text">Your Review</label><textarea id="rev-text" rows="4" placeholder="Share your experience..." required></textarea></div><button class="btn" type="submit">Submit Review</button></form></div></div></section>`}
function videoSection(){return `<section class="section"><div class="container"><div class="section-head"><div><p class="eyebrow">Experience the Fragrance</p><h2 class="display">See the Season.</h2></div></div><div class="video-grid"><div class="video-card"><span class="video-play"></span></div></div></div></section>`}
function productPage(p){if(!p)return notFound();const noteList=p.notes.split(' · ').map(n=>`<span class="note-tag">${n.trim()}</span>`).join('');return `<main id="main"><div class="container product-page"><div class="product-gallery"><img src="${p.image}" alt="${p.name} fragrance bottle"/><img src="/product/${p.slug}/2.png" alt="${p.name} infographic" class="pdp-infographic"/></div><div class="product-summary"><p class="crumb"><a href="/" data-link>Home</a> / <a href="/shop" data-link>Shop</a> / ${p.name}</p><h1 class="display">${p.name}</h1><p class="product-subtitle">${p.subtitle}</p><p class="pdp-description">${p.description}</p><p class="pdp-notes">${p.notes} · Extrait de Parfum · 50 ML</p><p class="price">${p.mrp&&p.mrp>p.price?`<del>₹${p.mrp.toLocaleString('en-IN')}</del> `:''}₹${p.price.toLocaleString('en-IN')} <span class="price-tax">incl. of all taxes</span></p><div class="purchase-row"><div class="qty"><button data-pdp-qty="-1" aria-label="Decrease quantity">−</button><span id="pdp-qty">1</span><button data-pdp-qty="1" aria-label="Increase quantity">+</button></div><button class="btn" data-add="${p.slug}" data-pdp-add>Add to Bag</button></div><div class="pdp-secondary-actions"><button data-wish="${p.slug}" class="${wishes.includes(p.slug)?'wish-active':''}">${wishes.includes(p.slug)?'♥ Saved to Wishlist':'♡ Add to Wishlist'}</button><span class="pdp-actions-divider"></span><button class="share-btn" data-share>Share</button></div><div class="detail-accordions"><details open><summary>The Story</summary><div class="accordion-body"><p>${p.description}</p></div></details><details><summary>The Character</summary><div class="accordion-body"><p>${p.character}. Created for the moments you want to remember.</p></div></details><details><summary>Fragrance Notes</summary><div class="accordion-body"><p>${p.notes}</p><div class="note-tags">${noteList}</div></div></details><details><summary>Details</summary><div class="accordion-body"><p>Extrait de Parfum · 50 ML</p><p>Crafted in India with intention and care.</p></div></details><details><summary>Delivery & Returns</summary><div class="accordion-body"><p>Complimentary shipping across India. Express delivery available at checkout.</p><p>Easy returns within 7 days of delivery.</p></div></details></div></div></div>${reviewSection(p)}<section class="section pdp-also-like"><div class="container"><div class="section-head"><div><p class="eyebrow">You May Also Like</p><h2 class="display">Continue the Season.</h2></div></div><div class="product-grid">${products.filter(x=>x.slug!==p.slug).slice(0,3).map(productCard).join('')}</div></div></section><div class="pdp-sticky-bar"><span class="sticky-name">${p.name}</span><button class="btn" data-add="${p.slug}" data-pdp-add>Add to Bag</button></div></main>`}
function collection(){return `<main id="main">${pageHero('The Collection','Six fragrances. One unforgettable season.','Six expressions of one idea — luxury that stays with you.')}<section class="section"><div class="container intro"><div><p class="eyebrow">Six moments</p><h2 class="display">Each creation is a way of remembering.</h2></div><div class="intro-body"><p>From rain-soaked earth and royal rose to golden amber and delicate florals, every creation takes a feeling and gives it a form through fragrance.</p>${link('/shop','Explore the Collection','text-link')}</div></div></section><section class="section signature"><div class="container"><div class="product-grid">${products.map(productCard).join('')}</div></div></section></main>`}
function aboutPage(){const cms=cmsPages.about||{};const heroTitle=cms.heroTitle||'Why We Began';const heroIntro=cms.heroIntro||'As we researched fragrances and the brands people admire, our curiosity brought us closer to home. We wanted to understand Indian perfumery, and the place an Indian brand could hold in modern luxury.';const identityHeading=cms.identityHeading||'Indian at Heart.<br/>Individual in Expression.';const identityBody=cms.identityBody||'';const luxuryHeading=cms.luxuryHeading||'Our Idea of Luxury';const foundersNote=cms.foundersNote||'';return `<main id="main" class="about-v5"><section class="about-hero"><div class="v3"><p class="v3-kicker">Our Story</p><h1 class="about-hero-title">${heroTitle}</h1><p class="about-hero-intro">${heroIntro}</p></div></section><section class="about-section about-split"><div class="v3 about-split-grid"><div class="about-split-text"><p class="v3-kicker">Our Identity</p><h2>${identityHeading}</h2><p>For us, an Indian identity is not something to hide behind an unfamiliar name or a borrowed sense of prestige. It is something to express with confidence.</p><p>India is where our story begins. It is not the only reason to choose us. We want The Sixth Ritu to feel connected to India while leaving room for a contemporary, personal idea of luxury, not limited to one image, one occasion or one kind of person.</p><p>Our world draws on the things around us: the anticipation of rain, the brightness of a new morning, the warmth of an evening that passes too quickly. These become personal when someone makes a fragrance their own. A scent may remind one person of home, and another of a fresh beginning. Our role is to offer an expression. Yours is to decide what it means.</p></div><div class="about-split-img"><img src="/welcome-vertical.webp" alt="The Sixth Ritu" loading="lazy"/></div></div></section><section class="about-section about-ritu"><div class="v3"><p class="v3-kicker">The Name</p><h2>Why The Sixth Ritu?</h2><p class="about-ritu-intro">Ritu is the Indian word for season. A season changes more than the landscape. It changes our pace, our surroundings and sometimes the way we see ourselves.</p><div class="about-seasons-visual"><div class="about-season-list"><span>Vasanta<small>Spring</small></span><span>Grishma<small>Summer</small></span><span>Varsha<small>Monsoon</small></span><span>Sharad<small>Autumn</small></span><span>Hemanta<small>Pre-Winter</small></span><span>Shishira<small>Winter</small></span></div><div class="about-sixth"><span>The Sixth Ritu</span><p>A personal season, shaped by mood, memory and individuality rather than a date on the calendar.</p></div></div><p class="about-ritu-close">The Sixth Ritu is not about becoming someone else. It is about finding a fragrance that belongs to the way you feel.</p></div></section><section class="about-section about-luxury"><div class="v3 about-split-grid about-split-reverse"><div class="about-split-img"><img src="/hero-roses.webp" alt="Luxury craftsmanship" loading="lazy"/></div><div class="about-split-text"><p class="v3-kicker">Our Philosophy</p><h2>Our Idea of Luxury</h2><p>We believe luxury should feel considered, not complicated.</p><p>It lives in the details, without needing to announce itself: a visual identity that feels coherent, a bottle you enjoy reaching for, a wooden cap engraved with our lotus, and a fragrance that becomes part of getting ready, stepping out, or taking a moment for yourself.</p><p>Everything we make is made with love and care, from the first idea to the last detail. That is what we want you to feel when you hold a bottle for the first time.</p><p class="about-luxury-accent">The most meaningful fragrance is not necessarily the one everyone recognises. It is the one you return to because it feels right on you, until it quietly becomes yours.</p></div></div></section><section class="about-section about-collection"><div class="v3"><div class="about-collection-head"><p class="v3-kicker">The Collection</p><h2>Our First Collection</h2><p>One fragrance does not have to express everything about a person. You may love something fresh and luminous, then be drawn to something deeper and warmer. Your choice can change with the occasion, your mood, or simply your curiosity.</p><p>We are beginning with six Extrait de Parfum fragrances, and the collection will grow as our story does. Each one is a different starting point. You may find a signature to wear every day, or different scents for different moments.</p><p class="about-luxury-accent">The pleasure is in discovering what speaks to you.</p></div><div class="v3-collection-grid about-collection-grid">${products.map(p=>`<div class=\"v3-prod-card\"><div class=\"v3-prod-card-img\"><a href=\"/product/${p.slug}\" data-link><img src=\"${p.image}\" alt=\"${p.name}\" loading=\"lazy\"/></a></div><h3><a href=\"/product/${p.slug}\" data-link>${p.name}</a></h3><p class=\"v3-prod-card-char\">${p.character}</p></div>`).join('')}</div>${link('/shop','Explore the Collection','v3-btn about-cta')}</div></section><section class="about-section about-founders"><div class="v3"><div class="about-founders-card"><p class="v3-kicker">A Note from the Founders</p><h2>Beginning a New Story</h2><p>We began with curiosity and a belief that an Indian fragrance brand could earn its place through its own identity.</p><p>We researched, explored and asked ourselves what we would want as customers. What would make us stop and discover a new name? What would make that first impression meaningful? And what would make us come back?</p><p>The Sixth Ritu is our answer.</p><p>We are not presenting a centuries-old family story. We are beginning a new one, with respect for where we come from and ambition for what we can create. We want you to choose our fragrances because you enjoy wearing them, and because they were made with love. We want you to see our Indian identity as a source of confidence, not a limitation.</p><p class="about-luxury-accent">That is the future we are working toward, one customer and one experience at a time.</p><div class="about-signature"><p class="about-sig-name">Mr. &amp; Mrs. Gandhi.</p><p class="about-sig-title">Founders, The Sixth Ritu</p></div></div></div></section></main>`}
function narrative(type){const content={about:['Our Story','A Season Beyond the Six','India has always known six seasons. Each transforms the world around us and leaves behind a feeling. The Sixth Ritu is the one we imagine — formed through fragrance, memory and the moments that stay with you.','Some Moments Pass. Others Become a Season of Their Own.'],ritu:['The Sixth Ritu','A season experienced through scent.','The Sixth Ritu is not a date on a calendar. It is rain after a storm, the warmth of a ritual, flowers resting on silk, or the memory of someone after they have gone.','Made to Be Worn. Created to Be Remembered.']}[type];return `<main id="main">${pageHero(content[0],content[1],content[2])}<section class="section"><div class="container info-layout"><div class="info-side">Indian imagination,<br/>contemporary fine fragrance.</div><div class="info-copy"><p class="eyebrow">Our Philosophy</p><h2>${content[3]}</h2><p>Every fragrance begins with a feeling. We translate that feeling through scent, bringing together expressive perfume ingredients and a modern approach to luxury. Each creation is designed to unfold gradually on the skin, revealing its character over time.</p><p>Like a season becoming a memory.</p></div></div></section><section class="seasons"><div class="seasons-content"><p class="eyebrow">The Inspiration</p><h2 class="display">Vasanta · Grishma<br/>Varsha · Sharad<br/>Hemanta · Shishira</h2><div class="seasons-final">THE SIXTH RITU</div><p>The Season of Luxury</p></div></section><section class="section"><div class="container"><div class="product-grid">${products.map(productCard).join('')}</div></div></section></main>`}
function contact(){return `<main id="main">${pageHero('Contact','Begin a conversation.','For enquiries, collection information or a note for our team.') }<section class="section"><div class="container contact-grid"><div><p class="eyebrow">Contact Us</p><h2 class="display" style="font-size:3rem;margin-top:0">We would love to hear from you.</h2><p>Share your details and our team will be in touch. Contact information will be added here once confirmed.</p></div><form data-contact novalidate><div class="field"><label for="name">Name</label><input id="name" required /></div><div class="field"><label for="email">Email</label><input id="email" type="email" required /></div><div class="field"><label for="phone">Phone</label><input id="phone" type="tel" /></div><div class="field"><label for="subject">Subject</label><input id="subject" required /></div><div class="field"><label for="message">Message</label><textarea id="message" required></textarea></div><p class="form-status" aria-live="polite"></p><button class="btn">Send Message</button></form></div></section></main>`}
function searchPage(){return `<main id="main">${pageHero('Search','Find your fragrance.')}<section class="section"><div class="container search-box"><input class="search-input" data-search-input placeholder="Search the collection" aria-label="Search the collection" autofocus/><div id="search-results" class="product-grid" style="margin-top:55px"></div></div></section></main>`}
function wishlistPage(){return `<main id="main">${pageHero('Wishlist','Your saved season.')}<section class="section"><div class="container" id="wishlist-page">${wishes.length?`<div class="product-grid">${wishes.map(bySlug).filter(Boolean).map(productCard).join('')}</div>`:empty('Your wishlist is waiting.','Explore the collection','/shop')}</div></section></main>`}
function empty(title,label,path){return `<div class="empty"><h3>${title}</h3><p>Keep the fragrances that speak to you close.</p>${link(path,label,'btn')}</div>`}
function cartPage(){return `<main id="main">${pageHero('Bag','Your Season.')}<section class="section"><div class="container" id="cart-page">${cartContent(true)}</div></section></main>`}
function cartContent(full=false){if(!cart.length)return `<div class="empty"><div class="empty-icon">◇</div><h3>Your bag is waiting.</h3><p>Keep the fragrances that speak to you close.</p>${link('/shop','Explore the Collection','btn')}</div>`;let rows=cart.map(i=>{let p=bySlug(i.slug);return `<div class="cart-item"><img src="${p.image}" alt="${p.name}"/><div class="cart-item-details"><h3>${p.name}</h3><p class="cart-item-variant">Extrait de Parfum \u00b7 50 ML</p><div class="qty"><button data-cart-qty="${p.slug}" data-change="-1">\u2212</button><span>${i.qty}</span><button data-cart-qty="${p.slug}" data-change="1">+</button></div></div><button class="remove" data-remove="${p.slug}">Remove</button></div>`}).join('');const sub=cart.reduce((a,i)=>a+bySlug(i.slug).price*i.qty,0);const disc=coupon==='TSR200'?200:0;const afterDisc=Math.max(0,sub-disc);const gstAmt=Math.round(afterDisc-afterDisc/1.18);const cartSlugs=cart.map(i=>i.slug);const recs=products.filter(p=>!cartSlugs.includes(p.slug)).slice(0,2);const recsHtml=recs.length?`<div class="cart-recs"><h4>You May Also Like</h4><div class="cart-rec-grid">${recs.map(r=>`<div class="cart-rec-card"><img src="${r.image}" alt="${r.name}"/><span class="rec-name">${r.name}</span><span class="rec-type">Extrait de Parfum</span><button class="rec-add" data-add="${r.slug}">Add to Bag</button></div>`).join('')}</div></div>`:'';return `${full?`<div style="max-width:740px">${rows}</div>`:rows}<div class="cart-coupon"><input type="text" id="coupon-input" placeholder="Coupon code" value="${coupon}" maxlength="10"/><button id="coupon-apply">${coupon==='TSR200'?'Remove':'Apply'}</button></div><div class="cart-summary"><div class="summary-row"><span>Subtotal</span><span>\u20b9${sub.toLocaleString('en-IN')}</span></div>${disc?`<div class="summary-row discount"><span>Discount (TSR200)</span><span>\u2212\u20b9${disc.toLocaleString('en-IN')}</span></div>`:''}<div class="summary-row"><span>Incl. GST</span><span>\u20b9${gstAmt.toLocaleString('en-IN')}</span></div><div class="summary-row"><span>Shipping</span><span>Complimentary</span></div><div class="summary-row total"><span>You Pay</span><span>\u20b9${afterDisc.toLocaleString('en-IN')}</span></div></div><div class="cart-actions">${link('/checkout','Proceed to Checkout','btn')}<span class="continue-link" data-close>Continue Shopping</span></div>${recsHtml}`}
function checkout(){const indianStates=['Andhra Pradesh','Arunachal Pradesh','Assam','Bihar','Chhattisgarh','Goa','Gujarat','Haryana','Himachal Pradesh','Jharkhand','Karnataka','Kerala','Madhya Pradesh','Maharashtra','Manipur','Meghalaya','Mizoram','Nagaland','Odisha','Punjab','Rajasthan','Sikkim','Tamil Nadu','Telangana','Tripura','Uttar Pradesh','Uttarakhand','West Bengal','Andaman and Nicobar Islands','Chandigarh','Dadra and Nagar Haveli and Daman and Diu','Delhi','Jammu and Kashmir','Ladakh','Lakshadweep','Puducherry'];return `<main id="main">${pageHero('Checkout','Complete your order.')}<section class="section"><div class="container tsr-checkout-grid"><form class="tsr-checkout-form" data-checkout novalidate><div class="tsr-checkout-section"><h3>Customer Details</h3><div class="tsr-field"><label>Full Name <span class="req">*</span></label><input type="text" name="fullname" required/></div><div class="tsr-field"><label>Mobile Number <span class="req">*</span></label><input type="tel" name="mobile" pattern="[0-9]{10}" maxlength="10" inputmode="numeric" required placeholder="10-digit mobile number"/></div><div class="tsr-field"><label>Email <span class="req">*</span></label><input type="email" name="email" required/></div></div><div class="tsr-checkout-section"><h3>Delivery Address</h3><div class="tsr-field"><label>Address Line 1 <span class="req">*</span></label><input type="text" name="address1" required/></div><div class="tsr-field"><label>Address Line 2</label><input type="text" name="address2"/></div><div class="tsr-field"><label>Landmark</label><input type="text" name="landmark" placeholder="Near..."/></div><div class="tsr-field-row"><div class="tsr-field"><label>City <span class="req">*</span></label><input type="text" name="city" required/></div><div class="tsr-field"><label>PIN Code <span class="req">*</span></label><input type="text" name="pin" pattern="[0-9]{6}" maxlength="6" inputmode="numeric" required placeholder="6-digit PIN"/></div></div><div class="tsr-field-row"><div class="tsr-field"><label>State <span class="req">*</span></label><select name="state" required><option value="">Select State / UT</option>${indianStates.map(s=>`<option value="${s}">${s}</option>`).join('')}</select></div><div class="tsr-field"><label>Country</label><input type="text" name="country" value="India" readonly/></div></div></div><p class="form-status" aria-live="polite"></p><button class="btn tsr-checkout-submit">Place Order</button></form><aside class="tsr-order-summary"><h2>Order Summary</h2>${cart.length?`<div class="tsr-order-items">${cart.map(i=>{let p=bySlug(i.slug);return `<div class="tsr-order-item"><img src="${p.image}" alt="${p.name}"/><div><h4>${p.name}</h4><p>Qty: ${i.qty}</p><p>₹${(p.price*i.qty).toLocaleString('en-IN')}</p></div></div>`}).join('')}</div><div class="cart-summary"><div class="summary-row"><span>Subtotal</span><span>\u20b9${(function(){const s=cart.reduce((a,i)=>a+bySlug(i.slug).price*i.qty,0);return s.toLocaleString('en-IN')})()}</span></div>${coupon==='TSR200'?'<div class="summary-row discount"><span>Discount (TSR200)</span><span>\u2212\u20b9200</span></div>':''}<div class="summary-row"><span>Incl. GST</span><span>\u20b9${Math.round((cart.reduce((a,i)=>a+bySlug(i.slug).price*i.qty,0)-(coupon==='TSR200'?200:0))-(cart.reduce((a,i)=>a+bySlug(i.slug).price*i.qty,0)-(coupon==='TSR200'?200:0))/1.18).toLocaleString('en-IN')}</span></div><div class="summary-row"><span>Shipping</span><span>Complimentary</span></div><div class="summary-row total"><span>You Pay</span><span>\u20b9${Math.max(0,cart.reduce((a,i)=>a+bySlug(i.slug).price*i.qty,0)-(coupon==='TSR200'?200:0)).toLocaleString('en-IN')}</span></div></div>`:'<p class="tsr-empty-cart">Your bag is empty. Add a fragrance before continuing.</p>'}<p class="form-note">Payment and shipping details will be confirmed at the next stage.</p></aside></div></section></main>`}
function account(){return `<main id="main">${pageHero('Account','Your Sixth Ritu.')}<section class="section"><div class="container"><div class="account-card"><h2 class="display" style="font-size:3rem;margin-top:0">Welcome.</h2><p>Sign-in and order history will be connected when the customer account service is ready.</p>${link('/account/orders','View order history','text-link')}</div></div></section></main>`}
function supportPage(title,copy){return `<main id="main">${pageHero('Customer Care',title,copy)}<section class="section"><div class="container info-layout"><div class="info-side">The details,<br/>considered.</div><div class="info-copy"><p>This page is ready for your confirmed customer-care information. We have intentionally not made unverified shipping, return, privacy, or terms promises.</p><p>For assistance with an order, please use the contact form while the service contact information is being finalised.</p>${link('/contact','Contact Us','text-link')}</div></div></section></main>`}
function faq(){return `<main id="main">${pageHero('Customer Care','Frequently Asked Questions.')}<section class="section"><div class="container"><div class="faq-grid"><div class="faq-category"><h3>Shopping & Orders</h3><div class="detail-accordions"><details open><summary>How can I choose a fragrance?</summary><p>Begin with the mood that feels closest to you. Our <a href="/shop" data-link>Shop</a> page lets you explore by character, or use the Mood Finder on our homepage to discover which Ritu suits you today.</p></details><details><summary>What concentration are your fragrances?</summary><p>All six fragrances are Extrait de Parfum (50 ML) \u2014 the highest concentration, offering exceptional longevity and depth that lasts throughout the day.</p></details><details><summary>How do I place an order?</summary><p>Browse our collection, add your chosen fragrances to the bag, and proceed to checkout. We accept all major payment methods and offer complimentary shipping across India.</p></details><details><summary>Can I use a discount code?</summary><p>Yes! Enter your coupon code in the cart drawer before checkout. New customers receive an exclusive welcome code upon signing up.</p></details></div></div><div class="faq-category"><h3>Shipping & Returns</h3><div class="detail-accordions"><details><summary>Do you offer free shipping?</summary><p>Yes, complimentary shipping is available on all orders across India. Express delivery options are available at checkout.</p></details><details><summary>How long does delivery take?</summary><p>Standard delivery takes 5\u20137 business days. Express delivery is 2\u20133 business days, depending on your location.</p></details><details><summary>What is your return policy?</summary><p>We offer easy returns within 7 days of delivery. The product must be unused and in its original packaging. Please contact our team to initiate a return.</p></details><details><summary>Do you ship internationally?</summary><p>Currently, we ship across India only. International shipping will be announced soon. Follow us for updates.</p></details></div></div><div class="faq-category"><h3>Product & Care</h3><div class="detail-accordions"><details><summary>How should I store my fragrance?</summary><p>Keep your fragrance away from direct sunlight and extreme temperatures. Store upright in a cool, dry place to preserve the character of the scent.</p></details><details><summary>How long does the fragrance last?</summary><p>As Extrait de Parfum, our fragrances offer 8\u201312 hours of wear. Longevity varies by skin type, climate, and application.</p></details><details><summary>Are your fragrances cruelty-free?</summary><p>Absolutely. None of our fragrances are tested on animals. We are committed to ethical and responsible beauty.</p></details><details><summary>Are the prices inclusive of tax?</summary><p>Yes, all prices displayed are inclusive of GST. The price you see is the price you pay.</p></details></div></div><div class="faq-category"><h3>About The Sixth Ritu</h3><div class="detail-accordions"><details><summary>What does \u201cThe Sixth Ritu\u201d mean?</summary><p>India has always known six seasons \u2014 Vasanta, Grishma, Varsha, Sharad, Hemanta, and Shishira. We imagine a seventh: a season experienced through scent, emotion, and memory.</p></details><details><summary>Where are your fragrances made?</summary><p>All our fragrances are crafted in India, blending fine Indian botanicals with precious global ingredients.</p></details><details><summary>How can I contact the team?</summary><p>Use the <a href="/contact" data-link>contact form</a> and our team will respond promptly. You can also reach us at our social channels @TheSixthRitu.</p></details></div></div></div></div></section></main>`}
const journalArticles=[{slug:'art-of-indian-perfumery',tag:'Craft',title:'The Art of Indian Perfumery',hero:'/hero banner 2.png',intro:'How ancient techniques meet modern luxury in every bottle.',body:[{h:'A Heritage of Scent',p:'India has been a land of fragrance for millennia. From the attars of Kannauj to the sacred incense of temples, scent has always been woven into the fabric of Indian life. The art of perfumery here is not merely a craft \u2014 it is a tradition that connects the earthly to the divine.'},{h:'From Earth to Essence',p:'The finest Indian perfumery begins with the raw material \u2014 sandalwood from Mysore, vetiver from Rajasthan, jasmine from Madurai. Each ingredient carries the character of its origin, the soil, the climate, the hands that harvested it.'},{h:'Modern Expression',p:'At The Sixth Ritu, we honour this heritage while embracing contemporary perfumery techniques. Our fragrances are composed with the precision of modern science and the soul of ancient tradition, creating something that feels both timeless and entirely new.'},{h:'The Extrait Difference',p:'We chose Extrait de Parfum \u2014 the highest concentration \u2014 because a fragrance meant to be remembered deserves to last. Our compositions unfold over hours, revealing layers of character that evolve with the wearer.'}]},{slug:'creating-your-fragrance-ritual',tag:'Ritual',title:'Creating Your Fragrance Ritual',hero:'/hero banner 3.png',intro:'Transform an everyday moment into something extraordinary.',body:[{h:'The Morning Ritual',p:'A fragrance ritual begins with intention. Before dressing, before the world demands your attention, take a moment. Hold the bottle. Let the cap release the first whisper of scent. This is your moment.'},{h:'Where to Apply',p:'Pulse points are where your fragrance speaks loudest \u2014 the wrists, behind the ears, the base of the throat. But the true secret is to spray where you want to be discovered: the nape of the neck, the inner elbow, the décolletage.'},{h:'Layering & Longevity',p:'For the richest experience, apply to moisturised skin. Fragrance clings to hydration. Some prefer a single scent; others layer two complementary fragrances \u2014 Dark Monsoon with Golden Ritual creates something deeply personal and utterly unique.'},{h:'Making It Yours',p:'A fragrance ritual is not about following rules. It is about creating a moment that belongs only to you. The spray that signals the beginning of an evening. The scent that accompanies every important meeting. The fragrance that becomes your signature.'}]},{slug:'why-india-has-six-seasons',tag:'Season',title:'Why India Has Six Seasons',hero:'/hero banner 4.png',intro:'The ancient wisdom behind the Sixth Ritu philosophy.',body:[{h:'Beyond Four Seasons',p:'While much of the world divides the year into four seasons, Indian tradition recognises six \u2014 each one a distinct chapter in the story of the year, each carrying its own mood, its own palette, its own fragrance.'},{h:'The Six Ritus',p:'Vasanta (Spring) brings new beginnings. Grishma (Summer) blazes with radiance. Varsha (Monsoon) washes the earth clean. Sharad (Autumn) brings clarity. Hemanta (Pre-Winter) wraps the world in golden warmth. Shishira (Winter) holds everything in rich stillness.'},{h:'The Unnamed Season',p:'But there is a seventh experience \u2014 one the ancient texts never codified. It lives between moments. In the trace of a fragrance on a letter. In the warmth of a memory triggered by a scent. In the feeling that remains long after the moment has passed.'},{h:'Becoming The Sixth Ritu',p:'This unnamed season became the inspiration for everything we create. Each of our six fragrances captures a different expression of this idea \u2014 that the most profound experiences are not bound by time or calendar, but by emotion and memory.'}]}];function journalArticle(a){if(!a)return notFound();return `<main id="main">${pageHero('The Fragrance Journal',a.title,a.intro)}<section class="section"><div class="container journal-article"><div class="journal-hero-img"><img src="${a.hero}" alt="${a.title}" loading="lazy"/></div>${a.body.map(b=>`<div class="journal-block"><h3>${b.h}</h3><p>${b.p}</p></div>`).join('')}<div class="journal-nav">${link('/journal','\u2190 Back to Journal','text-link')}</div></div></section></main>`}
function journalIndex(){return `<main id="main">${pageHero('The Fragrance Journal','Stories & Craft.','Explorations in fragrance, ritual, and the art of remembering.')}<section class="section"><div class="container"><div class="v3-journal-grid">${journalArticles.map(j=>`<a class="v3-journal-card" href="/journal/${j.slug}" data-link><div class="v3-journal-card-img"><img src="${j.hero}" alt="${j.title}" loading="lazy"/></div><span class="v3-journal-card-tag">${j.tag}</span><h3>${j.title}</h3><p>${j.intro}</p></a>`).join('')}</div></div></section></main>`}
function notFound(){return `<main id="main" class="not-found"><div><p class="eyebrow">The Season is elsewhere</p><h1>404</h1><h2 class="display" style="font-size:3rem">This page has passed into memory.</h2>${link('/','Return Home','btn')}</div></main>`}
